import { useEffect, useMemo, useState, type CSSProperties, type ReactNode } from 'react';
import { BrowserRouter, Link, NavLink, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom';
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { Activity, AlertCircle, ArrowRight, BarChart3, Bell, BriefcaseBusiness, Check, ChevronDown, ChevronRight, Clock3, Copy, Database, ExternalLink, FileSearch, Fingerprint, Globe2, LayoutDashboard, Menu, Moon, MoreHorizontal, Network, Plus, Search, Shield, ShieldCheck, Smartphone, Sparkles, Sun, Target, TrendingUp, UserRound, Users, X, Zap } from 'lucide-react';
import { analyze, getBrand, getCases, getDetections, isDemo } from '@/services/api';
import { brand as seedBrand, cases as seedCases, chartData } from '@/mocks/data';
import type { AnalyzeResponse, Brand, Case, Detection, Tier } from '@/types';
import '@/index.css';

const cls = (...values: (string | false | undefined)[]) => values.filter(Boolean).join(' ');
const tierLabel = (tier: Tier) => tier === 0 ? 'Official' : tier === 1 ? 'Review' : 'Escalate';
const tierTone = (tier: Tier) => tier === 0 ? 'official' : tier === 1 ? 'review' : 'escalate';

function TierBadge({ tier, compact = false }: { tier: Tier; compact?: boolean }) {
  return <span className={`badge badge-${tierTone(tier)}`}>{tier === 0 ? <Check size={compact ? 11 : 13} /> : tier === 1 ? <Clock3 size={compact ? 11 : 13} /> : <AlertCircle size={compact ? 11 : 13} />}{compact ? `Tier ${tier}` : tier === 0 ? 'OFFICIAL — EXCLUDED' : `TIER ${tier} · ${tierLabel(tier).toUpperCase()}`}</span>;
}
function ProvenanceChip({ value }: { value: Detection['provenance'] }) { return <span className="provenance"><span className="provenance-dot" />{value}</span>; }
function ScoreBar({ score, small = false }: { score: number | null; small?: boolean }) { return <div className={cls('score-wrap', small && 'score-small')}><span className="score-number">{score ?? '—'}</span>{score !== null && <span className="score-track"><span className={`score-fill ${score >= 80 ? 'fill-red' : score >= 45 ? 'fill-amber' : 'fill-green'}`} style={{ width: `${score}%` }} /></span>}</div>; }
function Skeleton({ className = '' }: { className?: string }) { return <div className={`skeleton ${className}`} />; }
function Toast({ text, onClose }: { text: string; onClose: () => void }) { return <div className="toast"><Check size={16} />{text}<button onClick={onClose}><X size={14} /></button></div>; }

function Landing() {
  return <div className="landing"><header className="landing-nav"><Link to="/" className="brand-mark"><span className="logo-box"><Shield size={20} /></span><span>Aegis<span>Shield</span></span></Link><nav><a href="#features">Features</a><a href="#how">How it works</a><a href="#explain">Demo</a></nav><Link className="button button-dark" to="/app">Open console <ArrowRight size={15} /></Link></header>
    <main><section className="hero container"><div className="hero-copy"><span className="eyebrow"><span className="live-dot" /> Digital risk protection</span><h1>Know about fake accounts and rogue apps <em>before your customers do.</em></h1><p className="hero-sub">AegisShield monitors social platforms and app stores, scores every look-alike, and tells you exactly why.</p><div className="hero-actions"><Link className="button button-primary" to="/app">Open console <ArrowRight size={16} /></Link><a className="button button-quiet" href="#how">See how it works <ChevronRight size={16} /></a></div><div className="hero-proof"><span><Check size={14} /> Official assets excluded</span><span><Check size={14} /> Plain-English reasons</span></div></div><div className="hero-demo"><div className="glow" /><div className="mini-window"><div className="mini-header"><span className="mini-title"><span className="logo-box small"><Shield size={13} /></span> AegisShield</span><span className="mini-live"><span className="live-dot" /> Live feed</span></div><div className="mini-kpis"><div><small>Total threats</small><strong>24</strong><span className="delta-up">+12.4%</span></div><div><small>Escalate</small><strong className="red-text">7</strong><span>Last 24h</span></div><div><small>Excluded</small><strong className="green-text">18</strong><span>Protected</span></div></div><div className="mini-list"><div className="mini-list-head"><span>Latest detections</span><span>Score</span></div>{seedCases.map((item, index) => <div className="mini-row" key={item.id}><span className={`mini-icon ${index === 1 ? 'app' : ''}`}>{index === 1 ? <Smartphone size={14} /> : <Users size={14} />}</span><span className="mini-asset"><strong>{index === 0 ? 'acme_bank_help' : index === 1 ? 'com.acme.mobile.pro' : 'acme-support'}</strong><small>{index === 1 ? 'Google Play' : 'Instagram'}</small></span><span className={`mini-score ${index === 2 ? 'amber' : 'red'}`}>{[91, 96, 78][index]}</span></div>)}</div><div className="mini-footer"><span><span className="live-dot" /> Monitoring 8 sources</span><span>Updated just now</span></div></div></div></section>
      <section className="trust container"><div><strong>100%</strong><span>Official assets excluded</span></div><div><strong>Plain English</strong><span>Reasons your team can act on</span></div><div><strong>24/7</strong><span>Live threat feed</span></div></section>
      <section id="features" className="section container"><SectionIntro eyebrow="One console. Every look-alike." title="Clarity when your brand is under pressure." text="AegisShield turns a noisy stream of social and app-store signals into prioritized, explainable work." /><div className="feature-grid"><FeatureCard icon={Users} title="Social Profile Monitoring" text="Find impersonators, copycats, and support scams across the channels your customers trust." /><FeatureCard icon={Smartphone} title="App Store Monitoring" text="Detect rogue mobile apps with similar names, icons, packages, and dangerous permissions." /><FeatureCard icon={Fingerprint} title="Brand Digital Twin" text="Give your protection model the exact handles, packages, domains, and allowlists to defend." /></div></section>
      <section id="how" className="section how-section"><div className="container"><SectionIntro eyebrow="How it works" title="From signal to decision in four steps." /><div className="steps">{[['01', 'Onboard your brand', 'Capture the official assets and the exceptions your team knows.'], ['02', 'Monitor sources', 'Watch social platforms, app stores, and the public web continuously.'], ['03', 'Score and explain', 'Every candidate gets a tier, a score, and human-readable reasons.'], ['04', 'Review and act', 'Open cases, collaborate with your team, and preserve evidence.']].map(([number, title, text]) => <div className="step" key={number}><span>{number}</span><div><h3>{title}</h3><p>{text}</p></div></div>)}</div></div></section>
      <section id="explain" className="section container explain"><div className="explain-copy"><span className="eyebrow">Explainable by default</span><h2>Every detection comes with a reason you can trust.</h2><p>No black boxes. AegisShield connects each score to the specific signal that caused it, so analysts can make a decision in seconds.</p><Link to="/app/analyzer" className="text-link">Try the analyzer <ArrowRight size={15} /></Link></div><div className="detection-card"><div className="detection-top"><div><span className="eyebrow">Detection · social profile</span><h3>acme-bank-verify</h3><span className="muted">Instagram · First seen 8m ago</span></div><div className="score-big"><strong>87</strong><span>risk score</span></div></div><div className="reason-list"><ReasonItem code="CHAR_SWAP" text="Character swap: 'acme-bank' vs 'acmebank'" /><ReasonItem code="ADDED_WORD" text="Added word: 'verify' suggests credential theft" /><ReasonItem code="IMAGE_MATCH" text="Profile image matches official brand assets" /></div><div className="detection-bottom"><TierBadge tier={2} /><ProvenanceChip value="public" /><span className="source-label"><Globe2 size={13} /> Instagram</span></div></div></section>
      <section className="section guarantee"><div className="container guarantee-inner"><div className="guarantee-icon"><ShieldCheck size={28} /></div><div><span className="eyebrow">A promise to your team</span><h2>Official assets are never flagged.</h2><p>Exact handle, package-name, and allowlist matches against your Brand Digital Twin are marked <strong>OFFICIAL — EXCLUDED</strong>, scored as an em dash, and kept out of threat workflows.</p></div><div className="official-example"><TierBadge tier={0} /><span>com.acme.mobile</span><small>Exact package match</small></div></div></section>
      <section className="cta container"><div><span className="eyebrow">See what is hiding in plain sight</span><h2>Protect the trust you built.</h2></div><Link to="/app" className="button button-primary">Open the console <ArrowRight size={16} /></Link></section></main><footer className="footer container"><Link to="/" className="brand-mark"><span className="logo-box"><Shield size={17} /></span><span>Aegis<span>Shield</span></span></Link><span>Digital risk protection for modern teams.</span><span>© 2026 AegisShield</span></footer></div>;
}
function SectionIntro({ eyebrow, title, text }: { eyebrow: string; title: string; text?: string }) { return <div className="section-intro"><span className="eyebrow">{eyebrow}</span><h2>{title}</h2>{text && <p>{text}</p>}</div>; }
function FeatureCard({ icon: Icon, title, text }: { icon: typeof Users; title: string; text: string }) { return <div className="feature-card"><div className="feature-icon"><Icon size={19} /></div><h3>{title}</h3><p>{text}</p><span className="feature-link">Explore capability <ArrowRight size={14} /></span></div>; }
function ReasonItem({ code, text }: { code: string; text: string }) { return <div className="reason-item"><span className="reason-code">{code}</span><span>{text}</span></div>; }

const navGroups = [{ label: 'Monitor', items: [{ to: '/app', label: 'Dashboard', icon: LayoutDashboard }, { to: '/app/analyzer', label: 'Analyzer', icon: Zap }, { to: '/app/evidence/det-1', label: 'Evidence', icon: FileSearch }] }, { label: 'Brand', items: [{ to: '/app/brand', label: 'Brand Profile', icon: Fingerprint }] }, { label: 'Investigate', items: [{ to: '/app/cases', label: 'Cases', icon: BriefcaseBusiness }, { to: '/app/campaigns', label: 'Campaigns', icon: Network }, { to: '/app/typosquat', label: 'Typosquat Finder', icon: Globe2 }, { to: '/app/clone', label: 'Clone Compare', icon: Copy }] }, { label: 'Labs', items: [{ to: '/app/mitm', label: 'MITM Demo', icon: Shield }, { to: '/app/model-monitor', label: 'Model Monitor', icon: BarChart3 }] }];
function AppShell({ children, dark, onTheme, brandData, onToast }: { children: ReactNode; dark: boolean; onTheme: () => void; brandData: Brand; onToast: (message: string) => void }) {
  const [mobileOpen, setMobileOpen] = useState(false);
  return <div className={cls('app-shell', dark && 'dark')}><aside className={cls('sidebar', mobileOpen && 'mobile-open')}><div className="side-top"><Link to="/app" className="brand-mark"><span className="logo-box"><Shield size={19} /></span><span>Aegis<span>Shield</span></span></Link><button className="icon-button mobile-close" onClick={() => setMobileOpen(false)}><X size={18} /></button></div><div className="workspace"><div className="workspace-mark">AB</div><div><strong>{brandData.name}</strong><small>Protection workspace</small></div><ChevronDown size={14} /></div><nav className="side-nav">{navGroups.map(group => <div className="nav-group" key={group.label}><span className="nav-label">{group.label}</span>{group.items.map(item => { const Icon = item.icon; return <NavLink end={item.to === '/app'} onClick={() => setMobileOpen(false)} className={({ isActive }) => cls('nav-item', isActive && 'active')} to={item.to} key={item.to}><Icon size={17} /><span>{item.label}</span>{item.label === 'Evidence' && <span className="nav-count">8</span>}</NavLink>; })}</div>)}</nav><div className="side-bottom"><div className="connection"><span className="live-dot" /><div><strong>Live monitoring</strong><small>{isDemo ? 'Demo data active' : 'API connected'}</small></div></div><button className="user-card" onClick={() => onToast('Profile settings are ready for your team.')}><span className="avatar">VP</span><span><strong>Victoria Park</strong><small>Analyst</small></span><MoreHorizontal size={16} /></button></div></aside><div className="app-main"><header className="topbar"><button className="icon-button menu-trigger" onClick={() => setMobileOpen(true)}><Menu size={19} /></button><div className="topbar-search"><Search size={16} /><input aria-label="Global search" placeholder="Search detections, cases, assets..." /></div><div className="topbar-actions"><span className="api-status"><span className="live-dot" /> <span className="status-copy">Connected</span></span>{isDemo && <span className="demo-pill">Demo data</span>}<button className="icon-button"><Bell size={18} /><i /></button><button className="theme-toggle" onClick={onTheme} aria-label="Toggle theme">{dark ? <Sun size={16} /> : <Moon size={16} />}</button><span className="top-avatar">VP</span></div></header><main className="page-content">{children}</main></div></div>;
}

function PageHeader({ eyebrow, title, text, action }: { eyebrow: string; title: string; text?: string; action?: ReactNode }) { return <div className="page-header"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1>{text && <p>{text}</p>}</div>{action && <div className="page-header-action">{action}</div>}</div>; }
function KpiCard({ label, value, detail, icon: Icon, tone }: { label: string; value: string; detail: string; icon: typeof Shield; tone: string }) { return <div className="kpi-card"><div className={`kpi-icon ${tone}`}><Icon size={17} /></div><span className="kpi-label">{label}</span><strong>{value}</strong><span className="kpi-detail">{detail}</span></div>; }
function Panel({ title, eyebrow, children, action, className = '' }: { title: string; eyebrow?: string; children: ReactNode; action?: ReactNode; className?: string }) { return <section className={`panel ${className}`}><div className="panel-head"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h2>{title}</h2></div>{action}</div>{children}</section>; }
function Dashboard({ onToast }: { onToast: (message: string) => void }) {
  const [items, setItems] = useState<Detection[]>([]); const [loading, setLoading] = useState(true); const [tab, setTab] = useState<'profile' | 'app'>('profile'); const [sort, setSort] = useState<'score' | 'time'>('score'); const navigate = useNavigate();
  useEffect(() => { getDetections().then(setItems).finally(() => setLoading(false)); }, []);
  const visible = useMemo(() => items.filter(item => item.asset_type === tab).sort((a, b) => sort === 'score' ? (b.score ?? -1) - (a.score ?? -1) : new Date(b.detected_at).getTime() - new Date(a.detected_at).getTime()), [items, tab, sort]);
  const threats = items.filter(item => !item.official); const tier2 = items.filter(item => item.tier === 2).length; const tier1 = items.filter(item => item.tier === 1).length; const official = items.filter(item => item.official).length;
  const simulate = () => { const newItem = { ...items[3], id: `live-${Date.now()}`, asset_name: 'acmebank-secure-contact', provenance: 'live' as const, detected_at: new Date().toISOString(), score: 92, tier: 2 as Tier, status: 'New' as const }; setItems(current => [newItem, ...current].slice(0, 50)); onToast('New live detection added to the threat feed.'); };
  return <><PageHeader eyebrow="Overview" title="Good morning, Victoria." text="Here is what is happening across your protected brand assets." action={<button onClick={simulate} className="button button-primary"><Activity size={15} /> Simulate live event</button>} /><div className="kpi-grid"><KpiCard label="Total threats" value={`${threats.length}`} detail="+12.4% from last week" icon={Target} tone="blue" /><KpiCard label="Tier 2 escalate" value={`${tier2}`} detail="Needs immediate action" icon={AlertCircle} tone="red" /><KpiCard label="Tier 1 review" value={`${tier1}`} detail="Awaiting review" icon={Clock3} tone="amber" /><KpiCard label="Official excluded" value={`${official}`} detail="Never flagged" icon={ShieldCheck} tone="green" /></div><div className="dashboard-grid"><Panel title="Live threat feed" eyebrow="Monitoring now" className="feed-panel" action={<span className="panel-status"><span className="live-dot" /> Live</span>}><div className="feed-list" aria-live="polite">{loading ? <><Skeleton className="feed-skeleton" /><Skeleton className="feed-skeleton" /><Skeleton className="feed-skeleton" /></> : items.slice(0, 5).map(item => <button className="feed-item" key={item.id} onClick={() => navigate(`/app/evidence/${item.id}`)}><span className={`feed-bar ${tierTone(item.tier)}`} /><span className={`feed-source ${item.asset_type === 'app' ? 'app' : ''}`}>{item.asset_type === 'app' ? <Smartphone size={15} /> : <Users size={15} />}</span><span className="feed-main"><strong>{item.asset_name}</strong><span>{item.platform_or_store} · {item.reason_codes[0]?.code ?? 'Official match'}</span></span><span className="feed-meta"><TierBadge tier={item.tier} compact /><ProvenanceChip value={item.provenance} /><small>{item.id.includes('live') ? 'just now' : `${Math.max(2, Math.round((Date.now() - new Date(item.detected_at).getTime()) / 3600000))}h ago`}</small></span><ChevronRight size={15} /></button>)}</div><button className="panel-link" onClick={() => navigate('/app/evidence/det-1')}>View all detections <ArrowRight size={14} /></button></Panel><div className="chart-stack"><Panel title="Threats by category" eyebrow="Distribution"><div className="donut-wrap"><ResponsiveContainer width="54%" height={155}><PieChart><Pie data={[{ name: 'Social profiles', value: threats.filter(i => i.asset_type === 'profile').length }, { name: 'Mobile apps', value: threats.filter(i => i.asset_type === 'app').length }]} innerRadius={48} outerRadius={68} paddingAngle={4} dataKey="value"><Cell fill="#4f46e5" /><Cell fill="#a5b4fc" /></Pie></PieChart></ResponsiveContainer><div className="donut-center"><strong>{threats.length}</strong><span>threats</span></div><div className="legend"><span><i className="indigo" /> Social profiles <b>{threats.filter(i => i.asset_type === 'profile').length}</b></span><span><i className="indigo-light" /> Mobile apps <b>{threats.filter(i => i.asset_type === 'app').length}</b></span></div></div></Panel><Panel title="Detections per day" eyebrow="Last 7 days"><ResponsiveContainer width="100%" height={137}><AreaChart data={chartData}><defs><linearGradient id="areaBlue" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#4f46e5" stopOpacity={0.18} /><stop offset="100%" stopColor="#4f46e5" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="#e4e4e7" strokeDasharray="3 3" vertical={false} /><XAxis dataKey="day" tickLine={false} axisLine={false} tick={{ fontSize: 10, fill: '#71717a' }} /><YAxis hide /><Tooltip /><Area type="monotone" dataKey="detections" stroke="#4f46e5" strokeWidth={2} fill="url(#areaBlue)" /></AreaChart></ResponsiveContainer></Panel></div></div><Panel title="Detection table" eyebrow="All monitored assets" action={<div className="table-actions"><button className={cls('tab', tab === 'profile' && 'active')} onClick={() => setTab('profile')}>Social profiles <span>{items.filter(i => i.asset_type === 'profile').length}</span></button><button className={cls('tab', tab === 'app' && 'active')} onClick={() => setTab('app')}>Mobile apps <span>{items.filter(i => i.asset_type === 'app').length}</span></button></div>}><div className="table-toolbar"><span>{visible.length} assets found</span><button className="sort-button" onClick={() => setSort(sort === 'score' ? 'time' : 'score')}>Sort: {sort === 'score' ? 'Highest score' : 'Newest'} <ChevronDown size={14} /></button></div><div className="data-table-wrap"><table className="data-table"><thead><tr><th>Asset</th><th>Brand match</th><th>Score</th><th>Tier</th><th>Top reason</th><th>Source</th><th>Status</th></tr></thead><tbody>{visible.slice(0, 9).map(item => <tr key={item.id} onClick={() => navigate(`/app/evidence/${item.id}`)}><td><div className="asset-cell"><span className={`asset-icon ${item.asset_type === 'app' ? 'app' : ''}`}>{item.asset_type === 'app' ? <Smartphone size={15} /> : <Users size={15} />}</span><span><strong>{item.asset_name}</strong><small>{item.platform_or_store}</small></span></div></td><td>{item.brand_match}</td><td><ScoreBar score={item.score} small /></td><td><TierBadge tier={item.tier} compact /></td><td><span className="reason-code muted-code">{item.reason_codes[0]?.code ?? 'EXACT_MATCH'}</span></td><td><ProvenanceChip value={item.provenance} /></td><td><span className={`status-dot status-${item.status.toLowerCase().replace(' ', '-')}`} />{item.status}</td></tr>)}</tbody></table></div></Panel><Panel title="Severity by hour" eyebrow="Today" className="severity-panel"><ResponsiveContainer width="100%" height={130}><BarChart data={[{h:'00',v:3},{h:'04',v:6},{h:'08',v:12},{h:'12',v:8},{h:'16',v:15},{h:'20',v:10},{h:'24',v:18}]}><CartesianGrid stroke="#e4e4e7" strokeDasharray="3 3" vertical={false} /><XAxis dataKey="h" tickLine={false} axisLine={false} tick={{ fontSize: 10, fill: '#71717a' }} /><YAxis hide /><Tooltip /><Bar dataKey="v" fill="#818cf8" radius={[3,3,0,0]} /></BarChart></ResponsiveContainer></Panel></>;
}

function Analyzer({ onToast }: { onToast: (message: string) => void }) {
  const [type, setType] = useState<'profile' | 'app' | 'url'>('profile'); const [form, setForm] = useState({ platform: 'Instagram', handle: '', displayName: '', bio: '', packageName: '', appName: '', developer: '', url: '' }); const [result, setResult] = useState<AnalyzeResponse | null>(null); const [loading, setLoading] = useState(false); const navigate = useNavigate();
  const update = (key: string, value: string) => setForm(current => ({ ...current, [key]: value }));
  const quickFill = (kind: string) => { if (kind === 'fake') { setType('profile'); setForm(current => ({ ...current, handle: 'acme_bank_help', displayName: 'Acme Bank Support', bio: 'Official help for all Acme customers' })); } else if (kind === 'app') { setType('app'); setForm(current => ({ ...current, appName: 'Acme Bank Secure', packageName: 'com.acme.mobile.pro', developer: 'Acme Digital Services' })); } else { setType('profile'); setForm(current => ({ ...current, handle: '@acmebank', displayName: 'Acme Bank', bio: 'Official account' })); } };
  const run = async () => { setLoading(true); try { const response = await analyze(form); setResult(response); } catch { onToast('The analyzer could not complete this check.'); } finally { setLoading(false); } };
  return <><PageHeader eyebrow="Investigation tool" title="Analyze an asset." text="Run a focused check against the Acme Bank Brand Digital Twin." action={<div className="quick-actions"><span>Quick fill</span><button onClick={() => quickFill('fake')}>Fake profile</button><button onClick={() => quickFill('app')}>Rogue app</button><button onClick={() => quickFill('official')}>Official asset</button></div>} /><div className="analyzer-layout"><Panel title="Asset details" eyebrow="Step 1 · Provide a candidate" className="analyzer-form"><div className="segmented">{[['profile', 'Social Profile', Users], ['app', 'Mobile App', Smartphone], ['url', 'URL', Globe2]].map(([key, label, Icon]) => { const ItemIcon = Icon as typeof Users; return <button key={key as string} className={type === key ? 'active' : ''} onClick={() => setType(key as 'profile' | 'app' | 'url')}><ItemIcon size={15} />{label as string}</button>; })}</div>{type === 'profile' && <><Field label="Platform"><select value={form.platform} onChange={event => update('platform', event.target.value)}><option>Instagram</option><option>X</option><option>Facebook</option><option>TikTok</option><option>LinkedIn</option></select></Field><div className="form-grid"><Field label="Handle"><input value={form.handle} onChange={event => update('handle', event.target.value)} placeholder="@candidate" /></Field><Field label="Display name"><input value={form.displayName} onChange={event => update('displayName', event.target.value)} placeholder="Candidate profile name" /></Field></div><Field label="Bio"><textarea value={form.bio} onChange={event => update('bio', event.target.value)} placeholder="Paste the profile bio" /></Field><div className="form-grid"><Field label="Follower count"><input placeholder="e.g. 12400" /></Field><Field label="Account age"><input placeholder="e.g. 4 months" /></Field></div></>}{type === 'app' && <><Field label="Store"><select><option>Google Play</option><option>App Store</option></select></Field><div className="form-grid"><Field label="App name"><input value={form.appName} onChange={event => update('appName', event.target.value)} placeholder="Candidate app name" /></Field><Field label="Package name"><input value={form.packageName} onChange={event => update('packageName', event.target.value)} placeholder="com.example.app" /></Field></div><Field label="Developer name"><input value={form.developer} onChange={event => update('developer', event.target.value)} placeholder="Publisher name" /></Field><Field label="Description"><textarea placeholder="Paste the store description" /></Field></>}{type === 'url' && <Field label="URL to check"><input value={form.url} onChange={event => update('url', event.target.value)} placeholder="https://candidate-domain.com" /></Field>}<button className="button button-primary full-width" onClick={run} disabled={loading}>{loading ? 'Analyzing candidate...' : 'Run analysis'} <ArrowRight size={16} /></button></Panel><div className="analysis-result">{!result && !loading ? <div className="result-empty"><div className="result-orbit"><Sparkles size={24} /></div><h2>Ready when you are.</h2><p>Complete the candidate details or use a quick-fill example to see an explainable risk assessment.</p><div className="result-list"><span><Check size={14} /> Brand similarity</span><span><Check size={14} /> Behavior signals</span><span><Check size={14} /> Plain-English reasons</span></div></div> : loading ? <Panel title="Analyzing candidate" eyebrow="Comparing with Brand Digital Twin"><Skeleton className="gauge-skeleton" /><Skeleton className="result-skeleton" /><Skeleton className="result-skeleton" /></Panel> : <ResultCard result={result!} onOpen={() => { onToast('Case draft created from this analysis.'); navigate('/app/cases'); }} />}</div></div></>;
}
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="field"><span>{label}</span>{children}</label>; }
function ResultCard({ result, onOpen }: { result: AnalyzeResponse; onOpen: () => void }) { return <div className="result-card"><div className="result-summary"><div className="gauge" style={{ '--gauge': `${result.score ?? 0}%` } as CSSProperties}><div><strong>{result.score ?? '—'}</strong><span>{result.official ? 'excluded' : 'risk score'}</span></div></div><div><span className="eyebrow">Analysis complete</span><h2>{result.official ? 'Official asset confirmed.' : result.tier === 2 ? 'Escalate this candidate.' : 'Review this candidate.'}</h2><p>{result.official ? 'This exact match is protected by your Brand Digital Twin and will not enter threat workflows.' : 'Signals indicate a meaningful relationship to your protected brand assets.'}</p><TierBadge tier={result.tier} /></div></div><div className="result-section"><div className="section-label">Component scores <span>How the result was formed</span></div>{result.components.map(component => <div className="component-row" key={component.label}><span>{component.label}</span><span className="component-track"><i style={{ width: `${Math.max(3, component.value)}%` }} /></span><strong>{component.value}</strong></div>)}</div><div className="result-columns"><div><div className="section-label">Reason codes</div>{result.reason_codes.length ? result.reason_codes.map(reason => <div className="reason-row" key={reason.code}><span className="reason-code">{reason.code}</span><span>{reason.message}</span></div>) : <div className="safe-note"><Check size={15} /> Exact match against an official protected asset.</div>}</div>{result.shap.length > 0 && <div><div className="section-label">Signal contributions <span>SHAP-style</span></div>{result.shap.map(signal => <div className="shap-row" key={signal.label}><span>{signal.label}</span><span className={`shap-bar ${signal.tone}`}><i style={{ width: `${Math.abs(signal.value) * 2.2}%` }} /></span><strong>{signal.value > 0 ? '+' : ''}{signal.value}</strong></div>)}</div>}</div>{!result.official && <button onClick={onOpen} className="button button-primary">Open case <ArrowRight size={15} /></button>}</div>; }

function BrandProfile({ onToast }: { onToast: (message: string) => void }) {
  const [data, setData] = useState(seedBrand); const [saved, setSaved] = useState(false); const [newAllow, setNewAllow] = useState(''); const protectedCount = data.domains.length + data.handles.length + data.packages.length + data.developers.length;
  const save = () => { setSaved(true); onToast('Brand Digital Twin saved successfully.'); setTimeout(() => setSaved(false), 2500); };
  const addAllow = () => { if (!newAllow.trim()) return; setData(current => ({ ...current, allowlist: [...current.allowlist, { value: newAllow.trim(), type: 'Partner', note: 'Added from workspace' }] })); setNewAllow(''); };
  return <><PageHeader eyebrow="Brand protection" title="Brand Digital Twin" text="The source of truth AegisShield uses to distinguish official assets from look-alikes." action={<button className="button button-primary" onClick={save}>{saved ? <Check size={15} /> : null}{saved ? 'Saved' : 'Save changes'}</button>} /><div className="brand-layout"><div className="brand-form"><Panel title="Protected identity" eyebrow="Official brand assets"><Field label="Company name"><input value={data.name} onChange={e => setData({ ...data, name: e.target.value })} /></Field><TagField label="Official domains" values={data.domains} onChange={values => setData({ ...data, domains: values })} /><TagField label="Social handles" values={data.handles} onChange={values => setData({ ...data, handles: values })} /><TagField label="App package names" values={data.packages} onChange={values => setData({ ...data, packages: values })} /><TagField label="Developer names" values={data.developers} onChange={values => setData({ ...data, developers: values })} /><div className="logo-upload"><div className="logo-preview"><ShieldCheck size={26} /></div><div><strong>Brand logo</strong><span>PNG, SVG or JPG · Preview only</span></div><button className="button button-secondary" onClick={() => onToast('Logo upload preview opened.')}>Choose file</button></div></Panel><Panel title="Allowlist" eyebrow="Known exceptions"><p className="panel-description">Allowlisted fan, parody, and partner assets remain visible but do not become threats.</p><div className="allow-list">{data.allowlist.map(item => <div className="allow-row" key={item.value}><span className="allow-icon"><Check size={14} /></span><span><strong>{item.value}</strong><small>{item.type} · {item.note}</small></span><button className="icon-button" onClick={() => setData(current => ({ ...current, allowlist: current.allowlist.filter(entry => entry.value !== item.value) }))}><X size={15} /></button></div>)}</div><div className="inline-add"><input value={newAllow} onChange={e => setNewAllow(e.target.value)} placeholder="Add a handle, domain or package" /><button className="button button-secondary" onClick={addAllow}><Plus size={15} /> Add</button></div></Panel></div><aside className="brand-summary"><div className="summary-card"><span className="eyebrow">Protection coverage</span><strong className="summary-number">{protectedCount}</strong><span>protected assets</span><div className="summary-breakdown"><span><Globe2 size={14} /> Domains <b>{data.domains.length}</b></span><span><Users size={14} /> Handles <b>{data.handles.length}</b></span><span><Smartphone size={14} /> Packages <b>{data.packages.length}</b></span></div></div><Panel title="Risk thresholds" eyebrow="Scoring policy"><p className="panel-description">Adjust when analysts should review or escalate a candidate.</p><Threshold label="Review at" value={data.thresholds.review} color="amber" onChange={value => setData({ ...data, thresholds: { ...data.thresholds, review: Math.min(value, data.thresholds.escalate - 1) } })} /><Threshold label="Escalate at" value={data.thresholds.escalate} color="red" onChange={value => setData({ ...data, thresholds: { ...data.thresholds, escalate: Math.max(value, data.thresholds.review + 1) } })} /><div className="threshold-note"><Check size={14} /> Valid range: Review must stay below Escalate.</div></Panel></aside></div></>;
}
function TagField({ label, values, onChange }: { label: string; values: string[]; onChange: (values: string[]) => void }) { const [value, setValue] = useState(''); const add = () => { if (value.trim()) { onChange([...values, value.trim()]); setValue(''); } }; return <div className="tag-field"><span>{label}</span><div className="tag-box">{values.map(item => <span className="tag" key={item}>{item}<button onClick={() => onChange(values.filter(current => current !== item))}><X size={12} /></button></span>)}<input value={value} onChange={e => setValue(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); add(); } }} onBlur={add} placeholder="Add and press enter" /></div></div>; }
function Threshold({ label, value, color, onChange }: { label: string; value: number; color: string; onChange: (value: number) => void }) { return <label className="threshold"><span>{label} <b>{value}</b></span><input type="range" min="1" max="99" value={value} onChange={e => onChange(Number(e.target.value))} className={color} /></label>; }

function Evidence({ onToast }: { onToast: (message: string) => void }) { const { id } = useParams(); const item = seedCases.find(caseItem => caseItem.detectionId === id) ? (seedCases.find(caseItem => caseItem.detectionId === id) as Case) : null; const source = useMemo(() => { const match = (window as unknown as { __detections?: Detection[] }).__detections; return match?.find(entry => entry.id === id); }, [id]); const fallback = { id: id ?? 'det-1', asset_name: item?.title.split(' ')[0] ?? 'acme_bank_help', platform_or_store: item?.type === 'app' ? 'Google Play' : 'Instagram', score: item?.tier === 2 ? 91 : 78, tier: item?.tier ?? 2, official: false, reason_codes: [{ code: 'IMAGE_MATCH', message: 'Profile image matches official brand assets' }, { code: 'ADDED_WORD', message: "Added word suggests support impersonation" }], provenance: 'public', detected_at: new Date(Date.now() - 3600000).toISOString(), asset_type: item?.type ?? 'profile', brand_match: 'Acme Bank', brand_id: 'brand-acme', status: 'New' } as Detection; const current = source ?? fallback; return <><PageHeader eyebrow="Evidence view" title={current.asset_name} text={`${current.platform_or_store} · Detection ${current.id}`} action={<div className="header-actions"><button className="button button-secondary" onClick={() => onToast('Marked as a false positive for review.')}>Mark false positive</button><button className="button button-primary" onClick={() => onToast('Case opened and assigned to you.')}>Open case <ArrowRight size={15} /></button></div>} /><div className="evidence-grid"><Panel title="Candidate asset" eyebrow="Observed evidence"><div className="profile-preview"><div className={`preview-avatar ${current.asset_type === 'app' ? 'app' : ''}`}>{current.asset_type === 'app' ? <Smartphone size={28} /> : <Users size={28} />}</div><div><h3>{current.asset_name}</h3><p>{current.platform_or_store}</p><TierBadge tier={current.tier} /></div></div><div className="evidence-meta"><span><small>First seen</small><strong>Today, 09:42</strong></span><span><small>Last seen</small><strong>Just now</strong></span><span><small>Provenance</small><ProvenanceChip value={current.provenance} /></span></div></Panel><Panel title="Official reference" eyebrow="Brand Digital Twin"><div className="profile-preview official-reference"><div className="preview-avatar official"><ShieldCheck size={28} /></div><div><h3>Acme Bank</h3><p>Official identity · {current.asset_type === 'app' ? 'com.acme.mobile' : '@acmebank'}</p><TierBadge tier={0} /></div></div><div className="reference-note"><Check size={15} /> Compared against {seedBrand.domains.length + seedBrand.handles.length + seedBrand.packages.length} protected brand assets.</div></Panel></div><div className="evidence-lower"><Panel title="Why this was flagged" eyebrow="Explainable score"><div className="evidence-score"><div><strong>{current.score}</strong><span>risk score</span></div><ScoreBar score={current.score} /></div>{current.reason_codes.map(reason => <div className="evidence-reason" key={reason.code}><span className="reason-code">{reason.code}</span><div><strong>{reason.variant_type ?? 'Signal detected'}</strong><p>{reason.message}</p></div></div>)}</Panel><Panel title="Component comparison" eyebrow="Candidate vs official"><Comparison label="Name similarity" candidate={94} official={100} /><Comparison label="Visual identity" candidate={88} official={100} /><Comparison label="Behavioral risk" candidate={76} official={4} /><Comparison label="Context match" candidate={82} official={100} /><div className="provenance-box"><Database size={16} /><span>Source provenance</span><ProvenanceChip value={current.provenance} /><small>Collected from monitored public sources.</small></div></Panel></div><Panel title="Evidence timeline" eyebrow="Chain of custody"><div className="timeline"><div><span className="timeline-dot red" /><strong>Detection created</strong><span>Today at 09:42 · {current.platform_or_store}</span></div><div><span className="timeline-dot amber" /><strong>Similarity confirmed</strong><span>Today at 09:43 · Brand Digital Twin comparison</span></div><div><span className="timeline-dot gray" /><strong>Awaiting analyst decision</strong><span>Now · No action taken</span></div></div></Panel></> }
function Comparison({ label, candidate, official }: { label: string; candidate: number; official: number }) { return <div className="comparison"><span>{label}</span><div><i style={{ width: `${candidate}%` }} /><b>{candidate}</b></div><div className="comparison-official"><i style={{ width: `${official}%` }} /><b>{official}</b></div></div>; }

function SecondaryPage({ kind, onToast }: { kind: string; onToast: (message: string) => void }) { const [filter, setFilter] = useState('All'); const [open, setOpen] = useState<Case | null>(null); const caseList = seedCases.filter(item => filter === 'All' || item.status === filter); if (kind === 'cases') return <><PageHeader eyebrow="Investigation" title="Cases" text="Track decisions and coordinate response across your team." action={<button className="button button-primary" onClick={() => onToast('New case draft created.') }><Plus size={15} /> New case</button>} /><Panel title="Case queue" eyebrow={`${caseList.length} active records`}><div className="filter-row"><div className="segmented compact">{['All', 'Open', 'In review', 'Closed'].map(item => <button className={filter === item ? 'active' : ''} onClick={() => setFilter(item)} key={item}>{item}</button>)}</div><span className="muted">Updated moments ago</span></div><div className="data-table-wrap"><table className="data-table"><thead><tr><th>Case</th><th>Type</th><th>Tier</th><th>Owner</th><th>Status</th><th>Updated</th></tr></thead><tbody>{caseList.map(item => <tr key={item.id} onClick={() => setOpen(item)}><td><strong>{item.title}</strong><small className="table-sub">{item.id}</small></td><td>{item.type === 'app' ? 'Mobile app' : 'Social profile'}</td><td><TierBadge tier={item.tier} compact /></td><td>{item.owner}</td><td><span className="status-dot status-open" />{item.status}</td><td>{item.updated}</td></tr>)}</tbody></table></div></Panel>{open && <div className="drawer-backdrop" onClick={() => setOpen(null)}><aside className="drawer" onClick={e => e.stopPropagation()}><button className="icon-button drawer-close" onClick={() => setOpen(null)}><X size={18} /></button><span className="eyebrow">{open.id}</span><h2>{open.title}</h2><TierBadge tier={open.tier} /><p className="drawer-note">{open.notes}</p><div className="activity"><span className="section-label">Activity</span>{['Detection created', 'Assigned to ' + open.owner, 'Similarity review completed'].map((activity, index) => <div key={activity}><span className="timeline-dot" /><span><strong>{activity}</strong><small>{index === 0 ? 'Today, 09:42' : index === 1 ? 'Today, 10:05' : 'Today, 10:14'}</small></span></div>)}</div><div className="drawer-actions"><button className="button button-primary" onClick={() => { onToast('Takedown request approved.'); setOpen(null); }}>Approve takedown</button><button className="button button-secondary" onClick={() => onToast('Case dismissed with audit log entry.')}>Dismiss</button><button className="text-button" onClick={() => onToast('Case escalated to legal review.')}>Escalate</button></div></aside></div>}</>;
  if (kind === 'campaigns') return <><PageHeader eyebrow="Investigation" title="Campaigns" text="See related detections that move together across sources." /><Panel title="Connected activity" eyebrow="Campaign cluster · AC-17" action={<span className="panel-status"><span className="live-dot" /> 12 linked assets</span>}><div className="network"><svg viewBox="0 0 800 360" role="img" aria-label="Campaign network graph"><line x1="400" y1="180" x2="190" y2="90" /><line x1="400" y1="180" x2="200" y2="280" /><line x1="400" y1="180" x2="610" y2="86" /><line x1="400" y1="180" x2="630" y2="275" /><line x1="190" y1="90" x2="90" y2="170" /><line x1="610" y1="86" x2="700" y2="170" /><text x="284" y="119">shared image</text><text x="505" y="118">same package</text><circle className="node-main" cx="400" cy="180" r="43" /><text className="node-label" x="400" y="176">Acme Bank</text><text className="node-sub" x="400" y="193">protected brand</text>{[['190','90','acme_bank_help','profile'],['200','280','acme-support','profile'],['610','86','com.acme.mobile.pro','app'],['630','275','acme-bank-verify','profile'],['90','170','acme_bank_news','profile'],['700','170','acmebank.vip','profile']].map(([x,y,label,type]) => <g key={label}><circle className={`node ${type === 'app' ? 'node-app' : ''}`} cx={x} cy={y} r="30" /><text className="node-label small" x={x} y={Number(y) - 3}>{label.length > 16 ? label.slice(0, 14) + '…' : label}</text><text className="node-sub" x={x} y={Number(y) + 11}>first seen 2d ago</text></g>)}</svg></div></Panel></>;
  if (kind === 'typosquat') return <Typosquat onToast={onToast} />;
  if (kind === 'clone') return <CloneCompare />;
  if (kind === 'mitm') return <Mitm onToast={onToast} />;
  return <ModelMonitor />;
}
function Typosquat({ onToast }: { onToast: (message: string) => void }) { const [domain, setDomain] = useState('acmebank.com'); const [searched, setSearched] = useState(true); const rows = [['acme-bAnk.com', 'Character swap', 'Yes', 'Yes', 'High'], ['acmebank-login.com', 'Added word', 'Yes', 'Yes', 'High'], ['acmebank.co', 'TLD variation', 'Yes', 'No', 'Medium'], ['acme-bank.com', 'Spacing change', 'No', 'No', 'Low'], ['acmebanksecure.com', 'Added word', 'Yes', 'Yes', 'High']]; return <><PageHeader eyebrow="Investigation" title="Typosquat Finder" text="Generate likely domain variants and prioritize active registrations." /><Panel title="Search protected domain" eyebrow="Domain permutations"><div className="search-form"><input value={domain} onChange={e => setDomain(e.target.value)} /><button className="button button-primary" onClick={() => { setSearched(false); setTimeout(() => setSearched(true), 350); onToast(`Generated permutations for ${domain}.`); }}>Find variants <Search size={15} /></button></div>{searched ? <div className="data-table-wrap"><table className="data-table"><thead><tr><th>Variant</th><th>Type</th><th>Registered</th><th>Active</th><th>Risk</th></tr></thead><tbody>{rows.map(row => <tr key={row[0]}><td><strong>{row[0]}</strong></td><td>{row[1]}</td><td><span className="table-check"><Check size={13} />{row[2]}</span></td><td>{row[3]}</td><td><TierBadge tier={row[4] === 'High' ? 2 : row[4] === 'Medium' ? 1 : 0} compact /></td></tr>)}</tbody></table></div> : <Skeleton className="table-skeleton" />}</Panel></>; }
function CloneCompare() { return <><PageHeader eyebrow="Investigation" title="Clone Compare" text="Compare a suspicious page against your official web presence." action={<button className="button button-secondary"><ExternalLink size={15} /> Open official site</button>} /><div className="clone-score"><div><span className="eyebrow">Overall similarity</span><strong>87%</strong><span>High-confidence visual clone</span></div><div className="clone-meter"><i /></div></div><div className="clone-grid"><Preview title="Candidate page" suspicious /><Preview title="Official reference" /></div><Panel title="Matched elements" eyebrow="7 visual and content matches"><div className="matched-grid">{['Logo and favicon', 'Navigation structure', 'Sign-in CTA', 'Hero headline', 'Footer legal links', 'Typography scale', 'Color tokens'].map(item => <span key={item}><Check size={14} />{item}</span>)}</div></Panel></>; }
function Preview({ title, suspicious = false }: { title: string; suspicious?: boolean }) { return <div className="preview-card"><div className="preview-toolbar"><span className="preview-dot red" /><span className="preview-dot amber" /><span className="preview-dot green" /><span>{title}</span></div><div className="page-mock"><div className="mock-nav"><span className={suspicious ? 'mock-logo bad' : 'mock-logo'}>{suspicious ? 'ACME' : 'Acme Bank'}</span><span>Help&nbsp;&nbsp; Sign in</span></div><div className="mock-hero"><small>WELCOME TO ACME BANK</small><strong>{suspicious ? 'Secure your account now' : 'Banking made clearer'}</strong><span>Simple, secure tools for your everyday money.</span><button>{suspicious ? 'Verify your account' : 'Get started'}</button></div><div className="mock-footer" /></div></div>; }
function Mitm({ onToast }: { onToast: (message: string) => void }) { const [revoked, setRevoked] = useState(false); return <><PageHeader eyebrow="Security lab" title="MITM Demo" text="A safe, visual simulation of how a session can be intercepted." /><Panel title="Session flow" eyebrow="Interactive simulation"><div className="mitm-flow"><FlowNode icon={UserRound} label="User" sub="Customer device" /><ArrowRight className="flow-arrow" /><FlowNode icon={AlertCircle} label="Attacker proxy" sub="Untrusted relay" danger /><ArrowRight className="flow-arrow" /><FlowNode icon={BriefcaseBusiness} label="Acme Bank" sub="Protected origin" safe /></div><div className={`session-banner ${revoked ? 'revoked' : ''}`}><span className="live-dot" /><div><strong>{revoked ? 'Session revoked' : 'Session active'}</strong><span>{revoked ? 'All tokens invalidated and customer notified.' : 'Signals are being monitored in real time.'}</span></div><button className="button button-secondary" onClick={() => { setRevoked(true); onToast('Session revoked and audit event recorded.'); }}>Revoke session</button></div></Panel><div className="mitm-lower"><Panel title="Live signals" eyebrow="Detection stream"><div className="signal-list">{[['Token relay detected', '09:42:16', 'red'], ['Origin mismatch', '09:42:18', 'amber'], ['TLS intact to bank', '09:42:20', 'green'], ['Customer prompt shown', '09:42:24', 'amber']].map(signal => <div key={signal[0]}><span className={`signal-dot ${signal[2]}`} /><strong>{signal[0]}</strong><small>{signal[1]}</small></div>)}</div></Panel><Panel title="What to watch" eyebrow="Analyst notes"><ul className="clean-list"><li><Check size={14} /> Origin and destination should stay aligned.</li><li><Check size={14} /> A prompt for credentials is always high risk.</li><li><Check size={14} /> Revoke ends the simulated session immediately.</li></ul></Panel></div></>; }
function FlowNode({ icon: Icon, label, sub, danger, safe }: { icon: typeof UserRound; label: string; sub: string; danger?: boolean; safe?: boolean }) { return <div className={cls('flow-node', danger && 'danger', safe && 'safe')}><Icon size={22} /><strong>{label}</strong><span>{sub}</span></div>; }
function ModelMonitor() { return <><PageHeader eyebrow="Security lab" title="Model Monitor" text="Measure how the detection model is performing over time." action={<span className="model-health"><span className="live-dot" /> Model healthy</span>} /><div className="kpi-grid model-kpis"><KpiCard label="Precision" value="94.8%" detail="+2.1% this month" icon={Target} tone="green" /><KpiCard label="Recall" value="91.2%" detail="+1.4% this month" icon={Activity} tone="blue" /><KpiCard label="Feedback accuracy" value="96.4%" detail="Based on 248 reviews" icon={Check} tone="green" /><KpiCard label="Drift score" value="0.08" detail="Within healthy range" icon={TrendingUp} tone="amber" /></div><div className="monitor-grid"><Panel title="Confusion matrix" eyebrow="Last 30 days"><div className="matrix"><div /><span>Predicted safe</span><span>Predicted risk</span><span>Actual safe</span><b className="matrix-good">1,842</b><b className="matrix-warn">38</b><span>Actual risk</span><b className="matrix-warn">24</b><b className="matrix-good">612</b></div></Panel><Panel title="Feedback accuracy" eyebrow="Weekly trend"><ResponsiveContainer width="100%" height={190}><LineChart data={[{week:'W1',accuracy:89},{week:'W2',accuracy:92},{week:'W3',accuracy:91},{week:'W4',accuracy:96},{week:'W5',accuracy:96}]}><CartesianGrid stroke="#e4e4e7" strokeDasharray="3 3" vertical={false} /><XAxis dataKey="week" tickLine={false} axisLine={false} /><YAxis domain={[80,100]} hide /><Tooltip /><Line type="monotone" dataKey="accuracy" stroke="#4f46e5" strokeWidth={2.5} dot={{ fill: '#4f46e5', r: 3 }} /></LineChart></ResponsiveContainer></Panel></div></>; }

function AppRoutes({ onToast }: { onToast: (message: string) => void }) { return <Routes><Route path="/" element={<Landing />} /><Route path="/app" element={<Dashboard onToast={onToast} />} /><Route path="/app/analyzer" element={<Analyzer onToast={onToast} />} /><Route path="/app/brand" element={<BrandProfile onToast={onToast} />} /><Route path="/app/evidence/:id" element={<Evidence onToast={onToast} />} /><Route path="/app/cases" element={<SecondaryPage kind="cases" onToast={onToast} />} /><Route path="/app/campaigns" element={<SecondaryPage kind="campaigns" onToast={onToast} />} /><Route path="/app/typosquat" element={<SecondaryPage kind="typosquat" onToast={onToast} />} /><Route path="/app/clone" element={<SecondaryPage kind="clone" onToast={onToast} />} /><Route path="/app/mitm" element={<SecondaryPage kind="mitm" onToast={onToast} />} /><Route path="/app/model-monitor" element={<SecondaryPage kind="model-monitor" onToast={onToast} />} /></Routes>; }
function Root() { const location = useLocation(); const [dark, setDark] = useState(false); const [toast, setToast] = useState<string | null>(null); const [brandData, setBrandData] = useState<Brand>(seedBrand); useEffect(() => { getBrand().then(setBrandData); getCases(); }, []); useEffect(() => { if (toast) { const timer = setTimeout(() => setToast(null), 3200); return () => clearTimeout(timer); } return undefined; }, [toast]); const isApp = location.pathname.startsWith('/app'); return <>{isApp ? <AppShell dark={dark} onTheme={() => setDark(value => !value)} brandData={brandData} onToast={setToast}><AppRoutes onToast={setToast} /></AppShell> : <AppRoutes onToast={setToast} />}{toast && <Toast text={toast} onClose={() => setToast(null)} />}</>; }
export default function App() { return <BrowserRouter><Root /></BrowserRouter>; }
